          </div>
          <Badge variant="secondary">شمسی</Badge>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-3 sm:grid-cols-2 sm:items-start">
            <Field>
              <FieldLabel>نوع بازه</FieldLabel>
              <Select
                items={[...TYPE_ITEMS]}
